import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Server Deploy","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/docker.md","filePath":"self-hosted/docker.md","lastUpdated":1788855895000}'),o={name:"self-hosted/docker.md"};function n(d,e,l,r,h,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h1><p>Server Deploy is the self-hosted Memoh stack for always-on, multi-user or multi-tenant usage. Use it when Memoh should run on a server, VM, or NAS, or when bots need to keep serving external channels while your desktop is offline.</p><p>This page documents the Docker Compose server deployment. For the native local client, see <a href="/self-hosted/desktop.html">Desktop Installation</a>.</p><p>The default Compose stack includes PostgreSQL, a pgvector database for memory embeddings, a one-shot migration job, the main server with an explicit workspace backend and in-process AI agent, the channel worker, and the web UI. PostgreSQL is the only supported database.</p><p>The official Compose stack uses the <code>containerd</code> workspace backend. The server image starts an embedded containerd and mounts the runtime files needed by bot workspaces. For Docker Engine and Apple backends, see <a href="/self-hosted/workspace-backends.html">Workspace backends</a>.</p><h2 id="service-architecture" tabindex="-1">Service Architecture <a class="header-anchor" href="#service-architecture" aria-label="Permalink to &quot;Service Architecture&quot;">​</a></h2><p>The Docker Compose stack consists of multiple services. Some are always started, others are optional and enabled via <code>--profile</code>:</p><table tabindex="0"><thead><tr><th>Service</th><th>Profile</th><th>Description</th></tr></thead><tbody><tr><td><strong>server</strong></td><td><em>(core)</em></td><td>Main Memoh server with the configured container runtime backend and in-process AI agent</td></tr><tr><td><strong>channel</strong></td><td><em>(core)</em></td><td>Channel worker (<code>memoh-channel</code>) that owns platform connections and webhooks; talks to the server over internal RPC</td></tr><tr><td><strong>web</strong></td><td><em>(core)</em></td><td>Web UI (Vue 3)</td></tr><tr><td><strong>postgres</strong></td><td><em>(core)</em></td><td>PostgreSQL database (system of record)</td></tr><tr><td><strong>pgvector</strong></td><td><em>(core)</em></td><td>PostgreSQL with <code>pgvector</code> used for optional memory embeddings; see <a href="/integrations/providers/memory/builtin.html">Built-in Memory</a></td></tr><tr><td><strong>migrate</strong></td><td><em>(core, one-shot)</em></td><td>Runs <code>memoh-server migrate up</code> before the server starts</td></tr><tr><td><strong>webhook-tunnel</strong></td><td><code>webhook-tunnel</code></td><td>Optional <code>cloudflared</code> quick tunnel that exposes the channel worker&#39;s webhook listener to the internet</td></tr><tr><td><strong>connect-it</strong></td><td><code>connectors</code></td><td>Co-hosted <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a> service backing bot <a href="/guides/connectors.html">connectors</a> (see below)</td></tr></tbody></table><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">Docker</a></li><li><a href="https://docs.docker.com/compose/install/" target="_blank" rel="noreferrer">Docker Compose v2</a></li><li>Git</li></ul><h2 id="one-click-server-deploy-recommended" tabindex="-1">One-Click Server Deploy (Recommended) <a class="header-anchor" href="#one-click-server-deploy-recommended" aria-label="Permalink to &quot;One-Click Server Deploy (Recommended)&quot;">​</a></h2><p>Run the official install script (requires Docker and Docker Compose):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>Run the installer as your normal user. Do not wrap the whole script in <code>sudo</code>; the script will use <code>sudo docker</code> internally only if Docker requires it. If you intentionally need to run the whole installer as root, set <code>MEMOH_ALLOW_ROOT_INSTALL=true</code> explicitly.</p><p>The script will:</p><ol><li>Check for Docker and Docker Compose</li><li>Detect whether this is a first-time install, an upgrade, or a reinstall</li><li>Prompt for configuration (workspace, data directory, admin credentials, JWT secret, Postgres password, and workspace backend notice)</li><li>Reuse the existing <code>config.toml</code> automatically during upgrades so database credentials stay aligned with the persisted PostgreSQL volume</li><li>Offer a clean reinstall mode that removes Memoh Docker containers, volumes, and network before starting again</li><li>Fetch the latest release tag from GitHub and clone the repository</li><li>Generate <code>config.toml</code> from the Docker template with your settings when needed</li><li>Refuse to upgrade legacy SQLite installs (PostgreSQL is the only supported database; choose a clean reinstall instead)</li><li>Pin Memoh Docker image versions to the release (for example, <code>v0.13.0</code> uses image tag <code>0.13.0</code>)</li><li>Provision co-hosted Connect-It on fresh installs — generate its credentials once, persist them in <code>.env</code>, and add the <code>connectors</code> profile (see <a href="#connect-it-connectors">Connect-It Connectors</a>)</li><li>Start <code>docker-compose.yml</code> (core services), adding the <code>connectors</code> and <code>webhook-tunnel</code> profiles when enabled</li><li>Print recent database, migration, and server logs automatically if startup fails</li></ol><p><strong>Silent install</strong> (use all defaults, no prompts):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>Defaults when running silently:</p><ul><li>Workspace: <code>~/memoh</code></li><li>Data directory: <code>~/memoh/data</code></li><li>Admin: <code>admin</code> / <code>admin123</code></li><li>JWT secret: auto-generated</li><li>Database: PostgreSQL (with the <code>pgvector</code> sidecar)</li><li>Postgres password: <code>memoh123</code></li><li>Webhook tunnel: disabled unless <code>MEMOH_WEBHOOK_TUNNEL_MODE=external</code></li></ul><p>If the script detects an existing Memoh installation in silent mode, it defaults to <strong>upgrade</strong> and reuses the previous <code>config.toml</code>. If Docker state exists but no reusable <code>config.toml</code> can be found, the script exits and asks you to choose an explicit reinstall.</p><p><strong>Force a clean reinstall</strong> (removes Memoh Docker data before starting again):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_INSTALL_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">reinstall</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>You can also pass the install mode as an argument:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reinstall</span></span></code></pre></div><p><strong>Install a specific version:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.13.0</span></span></code></pre></div><p>Or using the environment variable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_VERSION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">v0.13.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p><strong>Use China mainland mirror</strong> (for slow image pulls):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> USE_CN_MIRROR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><blockquote><p>Environment variables can be combined, e.g. <code>curl -fsSL https://memoh.sh | MEMOH_VERSION=v0.13.0 USE_CN_MIRROR=true sh</code></p></blockquote><p><strong>Expose channel webhooks through a Cloudflare quick tunnel</strong> (for platforms that need a public callback URL):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_WEBHOOK_TUNNEL_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">external</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><h3 id="installer-options" tabindex="-1">Installer Options <a class="header-anchor" href="#installer-options" aria-label="Permalink to &quot;Installer Options&quot;">​</a></h3><p>The install script accepts these flags after <code>sh -s --</code>:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-y</code>, <code>--yes</code></td><td>Run silently with defaults. The script also switches to silent mode automatically when no TTY is available.</td></tr><tr><td><code>--version &lt;tag&gt;</code>, <code>--version=&lt;tag&gt;</code></td><td>Install a specific Git tag, such as <code>v0.13.0</code>.</td></tr><tr><td><code>--install-mode &lt;mode&gt;</code>, <code>--install-mode=&lt;mode&gt;</code></td><td>Choose <code>auto</code>, <code>fresh</code>, <code>upgrade</code>, or <code>reinstall</code>.</td></tr><tr><td><code>--database-driver &lt;driver&gt;</code>, <code>--database-driver=&lt;driver&gt;</code></td><td>Accepted for compatibility; <code>postgres</code> is the only supported value.</td></tr><tr><td><code>--container-backend &lt;backend&gt;</code>, <code>--workspace-backend &lt;backend&gt;</code></td><td>Choose the workspace backend value written to config. One-click Docker Compose installs support <code>containerd</code> only; use manual deployment for <code>docker</code> or <code>apple</code>.</td></tr></tbody></table><h2 id="manual-install" tabindex="-1">Manual Install <a class="header-anchor" href="#manual-install" aria-label="Permalink to &quot;Manual Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/felinics/Memoh.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Memoh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conf/app.docker.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.toml</span></span></code></pre></div><p>Edit <code>config.toml</code> — at minimum change:</p><ul><li><code>admin.password</code> — Admin password</li><li><code>auth.jwt_secret</code> — Generate with <code>openssl rand -base64 32</code></li><li><code>postgres.password</code> — Database password (also set <code>POSTGRES_PASSWORD</code> env var to match)</li></ul><p>Then start the core services:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POSTGRES_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-db-password</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Add <code>--profile connectors</code> for co-hosted Connect-It and <code>--profile webhook-tunnel</code> for the Cloudflare webhook sidecar as needed.</p><blockquote><p>On macOS or if your user is in the <code>docker</code> group, <code>sudo</code> is not required.</p></blockquote><blockquote><p><strong>Important</strong>: <code>docker-compose.yml</code> mounts <code>./config.toml</code> by default. You must create this file before starting — running without it will fail.</p></blockquote><p>To enable <a href="/guides/connectors.html">connectors</a> in a manual deployment, generate the Connect-It credentials yourself and add the <code>connectors</code> profile:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_CONNECT_IT_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://connect-it:8421&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_CONNECT_IT_API_TOKEN=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cit_$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_CONNECT_IT_SECRET_KEY=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1:$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_CONNECT_IT_COOKIE_SECRET=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_CONNECT_IT_ADMIN_PASSWORD=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;choose-a-password&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POSTGRES_PASSWORD=your-db-password </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connectors</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Keep the same values across restarts (for example in an <code>.env</code> file) — the API token is what Memoh presents to Connect-It, and the secret key encrypts stored credentials. The install script does all of this automatically.</p><h3 id="china-mainland-mirror" tabindex="-1">China Mainland Mirror <a class="header-anchor" href="#china-mainland-mirror" aria-label="Permalink to &quot;China Mainland Mirror&quot;">​</a></h3><p>For users in mainland China who cannot access Docker Hub directly, uncomment the <code>registry</code> line in <code>config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">registry = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh.cn&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">image_pull_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;if_not_present&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # if_not_present, always, or never</span></span></code></pre></div><p>And add the China mirror compose overlay:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker/docker-compose.cn.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>The install script handles this automatically when you set <code>USE_CN_MIRROR=true</code>.</p><h2 id="access-points" tabindex="-1">Access Points <a class="header-anchor" href="#access-points" aria-label="Permalink to &quot;Access Points&quot;">​</a></h2><p>After startup:</p><table tabindex="0"><thead><tr><th>Service</th><th>URL</th></tr></thead><tbody><tr><td>Web UI</td><td><a href="http://localhost:8082" target="_blank" rel="noreferrer">http://localhost:8082</a></td></tr><tr><td>API</td><td><a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a></td></tr><tr><td>Connect-It admin console <em>(with the <code>connectors</code> profile)</em></td><td><a href="http://localhost:8421" target="_blank" rel="noreferrer">http://localhost:8421</a></td></tr></tbody></table><p>Default login: <code>admin</code> / <code>admin123</code> (change this in <code>config.toml</code>). The Connect-It admin login is <code>admin</code> plus the password generated by the installer (printed at the end of the install, stored in <code>.env</code>).</p><p>First startup may take 1–2 minutes while images are pulled and services initialize.</p><h2 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h2><p>The <code>config.toml</code> file controls all server behavior. Here is a summary of the available sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><code>[log]</code></td><td>Logging level and format (<code>info</code>, <code>debug</code>; <code>text</code>, <code>json</code>)</td></tr><tr><td><code>[server]</code></td><td>HTTP listen address (default <code>:8080</code>)</td></tr><tr><td><code>[admin]</code></td><td>Admin account credentials (username, password, email)</td></tr><tr><td><code>[auth]</code></td><td>JWT secret and token expiration</td></tr><tr><td><code>timezone</code></td><td>Server timezone (default <code>UTC</code>)</td></tr><tr><td><code>[database]</code></td><td>Database driver; <code>postgres</code> is the only supported value</td></tr><tr><td><code>[container]</code></td><td>Workspace backend selection plus common workspace image, pull policy, data path, runtime path, and CNI settings</td></tr><tr><td><code>[containerd]</code></td><td>Containerd socket path and namespace</td></tr><tr><td><code>[docker]</code></td><td>Docker Engine host override; empty uses Docker environment/default socket</td></tr><tr><td><code>[apple]</code></td><td>socktainer socket and binary overrides for the Apple backend</td></tr><tr><td><code>[postgres]</code></td><td>PostgreSQL connection (host, port, user, password, database, sslmode)</td></tr><tr><td><code>[pgvector]</code></td><td>Optional pgvector database used for memory embeddings (<code>enabled</code>, host, port, user, password, database, sslmode)</td></tr><tr><td><code>[internal_rpc]</code></td><td>Server/channel-worker RPC targets and shared secret for the split deployment</td></tr><tr><td><code>[webhook_tunnel]</code></td><td>Webhook tunnel mode (<code>disabled</code> or <code>external</code>) and <code>public_base_url</code></td></tr><tr><td><code>[registry]</code></td><td>Provider definitions directory</td></tr><tr><td><code>[connect_it]</code></td><td>Connect-It endpoint for <a href="/guides/connectors.html">connectors</a> (<code>base_url</code>, <code>api_token</code>); both empty disables the feature. The Compose environment overrides these via <code>MEMOH_CONNECT_IT_BASE_URL</code> / <code>MEMOH_CONNECT_IT_API_TOKEN</code>.</td></tr><tr><td><code>[web]</code></td><td>Web frontend host and port</td></tr><tr><td><code>[agent]</code></td><td>Tool output truncation limits: <code>tool_output_max_bytes</code> (default 65536), <code>tool_output_max_lines</code> (default 2000), <code>system_files_max_bytes</code> (default 32768). Oversized tool output keeps head and tail instead of being cut off blindly.</td></tr><tr><td><code>[session_runtime]</code></td><td>Session-state backend for multi-instance deployments; see <a href="#multi-instance-deployments">Multi-Instance Deployments</a></td></tr></tbody></table><h2 id="multi-instance-deployments" tabindex="-1">Multi-Instance Deployments <a class="header-anchor" href="#multi-instance-deployments" aria-label="Permalink to &quot;Multi-Instance Deployments&quot;">​</a></h2><p>A single-instance deployment needs none of this — session state lives in process memory by default, with a durable ledger in the database.</p><p>To run more than one Memoh server instance behind a load balancer, agent-turn session state must move to a shared backend. Configure the <code>[session_runtime]</code> block:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">session_runtime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redis&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # &quot;memory&quot; (default, single instance only) or &quot;redis&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cluster = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # declare multi-instance mode; requires backend = &quot;redis&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># state_ttl = &quot;24h&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># owner_lease_ttl = &quot;30s&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">session_runtime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redis://redis:6379/0&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># key_prefix = &quot;memoh:session_runtime:&quot;</span></span></code></pre></div><p>Notes:</p><ul><li><code>redis</code> speaks the Redis protocol; Valkey works too. The bundled Docker Compose stack does not include a Redis/Valkey service — add your own.</li><li>Setting <code>cluster = true</code> with the <code>memory</code> backend fails at startup by design.</li><li>With the Redis backend, the server checks Redis health at startup and refuses to start if it is unreachable.</li></ul><h2 id="common-commands" tabindex="-1">Common Commands <a class="header-anchor" href="#common-commands" aria-label="Permalink to &quot;Common Commands&quot;">​</a></h2><blockquote><p>Prefix with <code>sudo</code> on Linux if your user is not in the <code>docker</code> group.</p></blockquote><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # Stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Stop and remove Memoh Docker data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # View logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Update to latest images</span></span></code></pre></div><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>POSTGRES_PASSWORD</code></td><td><code>memoh123</code></td><td>PostgreSQL password (must match <code>postgres.password</code> in <code>config.toml</code>)</td></tr><tr><td><code>MEMOH_CONFIG</code></td><td><code>./config.toml</code></td><td>Path to the configuration file</td></tr><tr><td><code>MEMOH_DATA_DIR</code></td><td><code>~/memoh/data</code></td><td>Installer data directory value written to <code>.env</code>; currently reserved for future bind-mount support.</td></tr><tr><td><code>MEMOH_VERSION</code></td><td><em>(latest release)</em></td><td>Git tag to install (e.g. <code>v0.13.0</code>). Also pins Memoh Docker image versions without the leading <code>v</code> (for example, <code>0.13.0</code>).</td></tr><tr><td><code>MEMOH_INSTALL_MODE</code></td><td><code>auto</code></td><td>Install mode: <code>auto</code>, <code>fresh</code>, <code>upgrade</code>, or <code>reinstall</code></td></tr><tr><td><code>MEMOH_DATABASE_DRIVER</code></td><td><code>postgres</code></td><td>Accepted for compatibility; <code>postgres</code> is the only supported value</td></tr><tr><td><code>MEMOH_CONTAINER_BACKEND</code></td><td><code>containerd</code></td><td>Workspace backend. One-click Docker Compose installs support <code>containerd</code>; use manual deployment for <code>docker</code> or <code>apple</code>.</td></tr><tr><td><code>MEMOH_ALLOW_ROOT_INSTALL</code></td><td><code>false</code></td><td>Allow running the installer shell itself as root. Prefer leaving this unset and running the installer as a normal user.</td></tr><tr><td><code>MEMOH_WEBHOOK_TUNNEL_MODE</code></td><td><code>disabled</code></td><td><code>external</code> adds the <code>webhook-tunnel</code> profile (Cloudflare <code>cloudflared</code> sidecar) so channel webhooks get a public URL.</td></tr><tr><td><code>USE_CN_MIRROR</code></td><td><code>false</code></td><td>Set to <code>true</code> to use China mainland image mirrors</td></tr><tr><td><code>MEMOH_CONNECT_IT_MODE</code></td><td><code>embedded</code> on fresh installs; unchanged on upgrades</td><td><code>embedded</code> runs the co-hosted Connect-It (<code>connectors</code> profile); <code>disabled</code> turns connectors off.</td></tr><tr><td><code>MEMOH_CONNECT_IT_PUBLIC_BASE_URL</code></td><td><code>http://localhost:8421</code></td><td>Public URL for connector OAuth callbacks and the admin console. Set it when Memoh is used from other machines.</td></tr><tr><td><code>MEMOH_CONNECT_IT_PORT</code></td><td><code>8421</code></td><td>Host port for the Connect-It container.</td></tr><tr><td><code>MEMOH_CONNECT_IT_IMAGE</code></td><td><em>(pinned release)</em></td><td>Connect-It image override.</td></tr></tbody></table><p>The remaining <code>MEMOH_CONNECT_IT_*</code> values (admin password, secret key, cookie secret, API token) are credentials the installer generates once and persists in <code>.env</code>; there is normally no reason to set them by hand.</p>`,75)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
